import java.math.BigDecimal;
import java.time.Instant;
import java.util.*;

public class WalidatorCsv {
    record ValidatedUser(String userId, String name, String email, String country, BigDecimal points, Instant expiresAt) {}

    static Object waliduj(Map<String, String> w) {
        List<String> bledy = new ArrayList<>();
        String id = w.getOrDefault("user_id", "").trim();
        if (!id.matches("\\d+")) bledy.add("user_id niepoprawne: '" + id + "'");
        String name = w.getOrDefault("name", "").trim();
        if (name.isEmpty()) bledy.add("name wymagane");
        String email = w.getOrDefault("email", "").trim().toLowerCase(Locale.ROOT);
        if (!email.contains("@")) bledy.add("email niepoprawny");
        String country = w.getOrDefault("country", "").trim().toUpperCase(Locale.ROOT);
        if (!country.matches("[A-Z]{2}")) bledy.add("country niepoprawny");
        BigDecimal points = null;
        try {
            points = new BigDecimal(w.getOrDefault("points", "").trim());
            if (points.signum() < 0) bledy.add("points < 0");
        } catch (NumberFormatException e) { bledy.add("points nie jest liczba: '" + w.get("points") + "'"); }
        Instant exp = null;
        String e = w.getOrDefault("expires_at", "").trim();
        if (!e.isEmpty()) {
            try { exp = Instant.parse(e); } catch (Exception ex) { bledy.add("expires_at niepoprawne"); }
        }
        return bledy.isEmpty() ? new ValidatedUser(id, name, email, country, points, exp) : bledy;
    }

    public static void main(String[] args) {
        System.out.println(waliduj(Map.of("user_id", "42", "name", " Anna ", "email", "A@Example.TEST", "country", "pl", "points", "1500", "expires_at", "2026-12-31T00:00:00Z")));
        System.out.println(waliduj(Map.of("user_id", "00123", "name", "Jan", "email", "j@example.test", "country", "DE", "points", "10")));
        System.out.println(waliduj(Map.of("user_id", "7", "name", "Ola", "email", "o@example.test", "country", "PL", "points", "1500,5")));
        System.out.println(waliduj(Map.of("user_id", "x1", "name", "", "email", "brak", "country", "POL", "points", "-5")));
    }
}
Wiersz 1: poprawny (email a@example.test, country PL). Wiersz 2: poprawny, userId "00123" zachowany jako tekst. Wiersz 3: błąd points ('1500,5'). Wiersz 4: pięć błędów. Walidacja przed kontaktem z Redis pozwala przygotować raport dry-run i plik odrzuceń.

